static bool z_ascii_is_ws(unsigned char c) {
    return c == ' ' || c == '\t' || c == '\n'
        || c == '\v' || c == '\f' || c == '\r';
}

static z_t58_t z_t58_substring(const z_t58_t* self, uint64_t from, uint64_t to);
